CREATE TYPE "Gender" AS ENUM ('MALE', 'FEMALE', 'OTHER', 'PREFER_NOT_TO_SAY');
CREATE TYPE "MemberCategory" AS ENUM ('ORDINARY', 'COMMITTEE_MEMBER', 'ADMIN', 'EXECUTIVE', 'TREASURER', 'SECRETARY', 'ORGANIZER', 'MEMBER');
CREATE TYPE "EducationLevel" AS ENUM ('PRIMARY', 'SECONDARY', 'CERTIFICATE', 'DIPLOMA', 'BACHELORS', 'MASTERS', 'DOCTORATE', 'OTHER');
CREATE TYPE "IdentityVerificationStatus" AS ENUM ('NOT_REVIEWED', 'VERIFIED', 'REJECTED');
ALTER TABLE "users" ADD COLUMN "membershipNumber" TEXT, ADD COLUMN "approvalNotes" TEXT, ADD COLUMN "rejectionReason" TEXT, ADD COLUMN "approvedAt" TIMESTAMP(3), ADD COLUMN "rejectedAt" TIMESTAMP(3), ADD COLUMN "identityVerificationStatus" "IdentityVerificationStatus" NOT NULL DEFAULT 'NOT_REVIEWED';
CREATE UNIQUE INDEX "users_membershipNumber_key" ON "users"("membershipNumber");
CREATE TABLE "member_profiles" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "gender" "Gender", "dateOfBirth" TIMESTAMP(3), "address" TEXT, "familyBranch" TEXT, "nextOfKinName" TEXT, "nextOfKinPhone" TEXT, "nextOfKinRelationship" TEXT, "profession" TEXT, "skills" TEXT, "educationLevel" "EducationLevel", "achievements" TEXT, "mentorshipArea" TEXT, "interests" TEXT, "emergencyContactName" TEXT, "emergencyContactPhone" TEXT, "memberCategory" "MemberCategory", "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "member_profiles_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "member_profiles_userId_key" ON "member_profiles"("userId");
CREATE INDEX "member_profiles_familyBranch_idx" ON "member_profiles"("familyBranch");
CREATE INDEX "member_profiles_memberCategory_idx" ON "member_profiles"("memberCategory");
CREATE TABLE "consent_records" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "termsVersion" TEXT NOT NULL, "privacyVersion" TEXT NOT NULL, "acceptedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "ipAddress" TEXT, "userAgent" TEXT, CONSTRAINT "consent_records_pkey" PRIMARY KEY ("id"));
CREATE INDEX "consent_records_userId_acceptedAt_idx" ON "consent_records"("userId", "acceptedAt");
CREATE TABLE "login_events" ("id" TEXT NOT NULL, "userId" TEXT, "email" TEXT NOT NULL, "success" BOOLEAN NOT NULL, "reason" TEXT, "ipAddress" TEXT, "userAgent" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "login_events_pkey" PRIMARY KEY ("id"));
CREATE INDEX "login_events_userId_createdAt_idx" ON "login_events"("userId", "createdAt");
CREATE INDEX "login_events_email_createdAt_idx" ON "login_events"("email", "createdAt");
CREATE TABLE "rate_limits" ("id" TEXT NOT NULL, "key" TEXT NOT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "windowStart" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "blockedUntil" TIMESTAMP(3), "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "rate_limits_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "rate_limits_key_key" ON "rate_limits"("key");
CREATE TABLE "membership_sequences" ("year" INTEGER NOT NULL, "lastValue" INTEGER NOT NULL DEFAULT 0, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "membership_sequences_pkey" PRIMARY KEY ("year"));
ALTER TABLE "member_profiles" ADD CONSTRAINT "member_profiles_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "consent_records" ADD CONSTRAINT "consent_records_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "login_events" ADD CONSTRAINT "login_events_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
